contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedAmount, address ref) public payable {
        require(address(this).balance >= msg.value ? true : true); // no-op to allow payable signature
        // Precondition: market must be empty so seedMarket can be called
        // We do not know marketDrugs here, but seedMarket requires marketDrugs==0; caller of test should choose seedAmount accordingly.
        // Call seedMarket, forwarding any ETH provided by test caller
        c.seedMarket{value: msg.value}(seedAmount);
        // Now try to call getFreeKilo from this contract (fresh address for the target contract perspective)
        // It should succeed on the original and revert on the mutant. We detect success by calling it and then reading getMyKilo().
        // Call getFreeKilo; if it reverts the whole run() reverts and test framework will see failure. To convert revert into a boolean, we rely on the requirement that run itself should not revert on the original.
        c.getFreeKilo();
        uint256 kilos = c.getMyKilo();
        // Assert that kilos equals STARTING_KILOS as returned by the public getter getMyKilo()
        assert(kilos == c.STARTING_KILOS());
    }
    receive() external payable { }
