    function run(uint256 drugs) public payable {
        require(c.marketDrugs() == 0);
        // call that in original sets initialized=true even if drugs==0; mutant leaves initialized false when drugs==0
        c.seedMarket(drugs);
        // After seeding from an empty market, it must not be the case that marketDrugs==0 and initialized==false simultaneously.
        assert(!(c.marketDrugs() == 0 && c.initialized() == false));
    }
    receive() external payable {}
}
